import { ProfilePatch } from './types';

const ALLOWED_KEYS = new Set<PropertyKey>(['displayName', 'tags']);
const DISPLAY_NAME_MAX_LENGTH = 40;
const TAGS_MAX_COUNT = 5;
const TAG_MAX_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

function isPlainObject(value: unknown): value is object {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Reads an own data property without consulting the prototype chain or running getters.
function ownDataValue(source: object, key: string): { value: unknown } | undefined {
  const descriptor = Object.getOwnPropertyDescriptor(source, key);
  if (descriptor === undefined) return undefined;
  if (!('value' in descriptor)) invalid();
  return { value: descriptor.value };
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > DISPLAY_NAME_MAX_LENGTH) invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value) || value.length > TAGS_MAX_COUNT) invalid();
  const seen = new Set<string>();
  const tags: string[] = [];
  for (let i = 0; i < value.length; i++) {
    const item: unknown = value[i];
    if (typeof item !== 'string') invalid();
    const trimmed = item.trim();
    if (trimmed.length < 1 || trimmed.length > TAG_MAX_LENGTH || seen.has(trimmed)) invalid();
    seen.add(trimmed);
    tags.push(trimmed);
  }
  return tags;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (!isPlainObject(input)) invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (!ALLOWED_KEYS.has(key)) invalid();
  }
  const displayName = ownDataValue(input, 'displayName');
  const tags = ownDataValue(input, 'tags');
  return {
    displayName: displayName
      ? { kind: 'set', value: parseDisplayName(displayName.value) }
      : { kind: 'keep' },
    tags: tags ? { kind: 'set', value: parseTags(tags.value) } : { kind: 'keep' },
  };
}

